/**
 * Verifiable ownership for mutations of hot files.
 *
 * The ownership table is deliberately small: it provides a CAS-like owner
 * claim and token-checked release. Actual writes are always submitted to the
 * existing per-file mutation queue supplied by the caller; this module does
 * not contain a scheduler of its own.
 */

export type HotFileOwner = string;
export type HotFileOwnerToken = string;

export interface HotFileWriteHolder {
  readonly filePath: string;
  readonly owner: HotFileOwner;
  readonly token: HotFileOwnerToken;
}

export type HotFileWriteClaim =
  | {
      readonly claimed: true;
      readonly reentrant: boolean;
      readonly holder: HotFileWriteHolder;
    }
  | {
      readonly claimed: false;
      readonly reentrant: false;
      readonly holder: HotFileWriteHolder;
    };

export type HotFileWriteRelease =
  | { readonly released: true }
  | { readonly released: false; readonly holder: HotFileWriteHolder | null };

/**
 * The queue is an adapter over the already-existing file mutation lease
 * kernel. Implementations must serialize operations for the same file while
 * allowing operations for different files to proceed independently.
 */
export interface HotFileMutationQueue {
  runExclusive<T>(filePath: string, operation: () => Promise<T> | T): Promise<T>;
}

export interface HotFileWriteOwnerOptions {
  /** The caller-provided queue. No fallback scheduler is installed here. */
  readonly queue: HotFileMutationQueue;
}

export interface HotFileWriteOperationOptions {
  readonly owner: HotFileOwner;
  readonly token: HotFileOwnerToken;
  readonly queue: HotFileMutationQueue;
}

interface OwnerRecord extends HotFileWriteHolder {
  /** Incremented on re-entry, but intentionally not exposed as a conflict. */
  reentries: number;
}

function validateIdentity(value: string, name: string): string {
  if (typeof value !== "string" || value.length === 0) {
    throw new TypeError(`${name} must be a non-empty string`);
  }
  return value;
}

/**
 * A registry for one runtime. Claims are atomic within the JavaScript
 * execution context because each claim performs its compare-and-set without an
 * intervening await.
 */
export class HotFileWriteOwnerRegistry {
  readonly #holders = new Map<string, OwnerRecord>();

  claim(
    filePath: string,
    owner: HotFileOwner,
    token: HotFileOwnerToken,
  ): HotFileWriteClaim {
    validateIdentity(filePath, "filePath");
    validateIdentity(owner, "owner");
    validateIdentity(token, "token");

    const current = this.#holders.get(filePath);
    if (current !== undefined) {
      if (current.owner === owner) {
        current.reentries += 1;
        return {
          claimed: true,
          reentrant: true,
          holder: this.#publicHolder(current),
        };
      }

      return {
        claimed: false,
        reentrant: false,
        holder: this.#publicHolder(current),
      };
    }

    const holder: OwnerRecord = {
      filePath,
      owner,
      token,
      reentries: 0,
    };
    this.#holders.set(filePath, holder);
    return {
      claimed: true,
      reentrant: false,
      holder: this.#publicHolder(holder),
    };
  }

  release(
    filePath: string,
    owner: HotFileOwner,
    token: HotFileOwnerToken,
  ): HotFileWriteRelease {
    validateIdentity(filePath, "filePath");
    validateIdentity(owner, "owner");
    validateIdentity(token, "token");

    const current = this.#holders.get(filePath);
    if (current === undefined) {
      return { released: false, holder: null };
    }
    if (current.owner !== owner || current.token !== token) {
      return { released: false, holder: this.#publicHolder(current) };
    }

    this.#holders.delete(filePath);
    return { released: true };
  }

  holder(filePath: string): HotFileWriteHolder | null {
    const current = this.#holders.get(filePath);
    return current === undefined ? null : this.#publicHolder(current);
  }

  /**
   * Run a write under an ownership claim and the caller's existing mutation
   * queue. A thrown operation rolls the claim back. The claim is also
   * released after a successful operation, allowing a later owner to proceed.
   */
  async run<T>(
    filePath: string,
    owner: HotFileOwner,
    token: HotFileOwnerToken,
    operation: () => Promise<T> | T,
    queue: HotFileMutationQueue,
  ): Promise<T> {
    const claim = this.claim(filePath, owner, token);
    if (!claim.claimed) {
      throw new HotFileWriteConflictError(claim.holder);
    }

    try {
      return await queue.runExclusive(filePath, operation);
    } finally {
      // If the operation released the claim itself, this is harmless. If it
      // failed, this is the rollback that prevents an ownership leak.
      this.release(filePath, owner, token);
    }
  }

  #publicHolder(record: OwnerRecord): HotFileWriteHolder {
    return {
      filePath: record.filePath,
      owner: record.owner,
      token: record.token,
    };
  }
}

export class HotFileWriteConflictError extends Error {
  readonly holder: HotFileWriteHolder;

  constructor(holder: HotFileWriteHolder) {
    super(
      `hot file ${holder.filePath} is owned by ${holder.owner}; write conflict`,
    );
    this.name = "HotFileWriteConflictError";
    this.holder = holder;
  }
}

const defaultRegistry = new HotFileWriteOwnerRegistry();

export function claimHotFileWriteOwner(
  filePath: string,
  owner: HotFileOwner,
  token: HotFileOwnerToken,
  registry: HotFileWriteOwnerRegistry = defaultRegistry,
): HotFileWriteClaim {
  return registry.claim(filePath, owner, token);
}

export function releaseHotFileWriteOwner(
  filePath: string,
  owner: HotFileOwner,
  token: HotFileOwnerToken,
  registry: HotFileWriteOwnerRegistry = defaultRegistry,
): HotFileWriteRelease {
  return registry.release(filePath, owner, token);
}

export function getHotFileWriteHolder(
  filePath: string,
  registry: HotFileWriteOwnerRegistry = defaultRegistry,
): HotFileWriteHolder | null {
  return registry.holder(filePath);
}

export function withHotFileWriteOwner<T>(
  filePath: string,
  owner: HotFileOwner,
  token: HotFileOwnerToken,
  operation: () => Promise<T> | T,
  queue: HotFileMutationQueue,
  registry: HotFileWriteOwnerRegistry = defaultRegistry,
): Promise<T> {
  return registry.run(filePath, owner, token, operation, queue);
}

/** Short aliases for callers that use acquire/commit terminology. */
export const acquireHotFileWriteOwner = claimHotFileWriteOwner;
export const commitHotFileWriteOwner = releaseHotFileWriteOwner;
export const runWithHotFileWriteOwner = withHotFileWriteOwner;

