  /** The caller-provided queue. No fallback scheduler is installed here. */
  readonly queue: HotFileMutationQueue;
}

export interface HotFileWriteOperationOptions {
  readonly owner: HotFileOwner;
  readonly token: HotFileOwnerToken;
  readonly queue: HotFileMutationQueue;
}

interface OwnerRecord extends HotFileWriteHolder {
  /** Incremented on re-entry, but intentionally not exposed as a conflict. */
  reentries: number;
}

function validateIdentity(value: string, name: string): string {
  if (typeof value !== "string" || value.length === 0) {
    throw new TypeError(`${name} must be a non-empty string`);
  }
  return value;
}

