 * execution context because each claim performs its compare-and-set without an
 * intervening await.
 */
export class HotFileWriteOwnerRegistry {
  readonly #holders = new Map<string, OwnerRecord>();

  claim(
    filePath: string,
    owner: HotFileOwner,
    token: HotFileOwnerToken,
  ): HotFileWriteClaim {
    validateIdentity(filePath, "filePath");
    validateIdentity(owner, "owner");
    validateIdentity(token, "token");

    const current = this.#holders.get(filePath);
    if (current !== undefined) {
      if (current.owner === owner) {
        current.reentries += 1;
        return {
          claimed: true,
          reentrant: true,
          holder: this.#publicHolder(current),
        };
      }

      return {
        claimed: false,
        reentrant: false,
        holder: this.#publicHolder(current),
      };
    }

    const holder: OwnerRecord = {
      filePath,
      owner,
      token,
      reentries: 0,
    };
    this.#holders.set(filePath, holder);
    return {
      claimed: true,
      reentrant: false,
      holder: this.#publicHolder(holder),
    };
  }

  release(
    filePath: string,
    owner: HotFileOwner,
    token: HotFileOwnerToken,
  ): HotFileWriteRelease {
    validateIdentity(filePath, "filePath");
    validateIdentity(owner, "owner");
    validateIdentity(token, "token");

    const current = this.#holders.get(filePath);
    if (current === undefined) {
      return { released: false, holder: null };
    }
    if (current.owner !== owner || current.token !== token) {
      return { released: false, holder: this.#publicHolder(current) };
    }

    this.#holders.delete(filePath);
    return { released: true };
  }

